result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "csv_to_resource/converter.py", "content": """"CSV-to-resource converter: flat CSV rows -> Patient/Observation-like JSON dicts.

Input CSV must have this header (order-insensitive):

    id,family,given,birthdate,gender,glucose_mg_dl

Row validation rules:
  * ``id`` is required and must be unique across rows.
  * ``birthdate`` must be a real calendar date in ISO ``YYYY-MM-DD`` form
    (so e.g. 1990-02-29 is rejected: 1990 is not a leap year) and must not
    be in the future relative to the conversion run date.
  * ``gender``, if present, must be one of male/female/other/unknown.
  * ``given`` may be empty -- that is explicitly ALLOWED.
  * ``glucose_mg_dl``, if present, must parse as a positive float.

Bad rows never crash the run; they are routed to ``rejects`` with reasons.

Output shape (see tests/golden/patients.expected.json for the canonical example):

{
  "patients": [
    {
      "resourceType": "Patient",
      "id": "p1",
      "name": [{"family": "Stone", "given": ["Ada"]}],
      "birthDate": "1980-01-15",
      "gender": "female"
    },
    ...
  ],
  "observations": [
    {
      "resourceType": "Observation",
      "id": "obs-p1-glucose",
      "status": "final",
      "category": [{"coding": [{"system": "http://terminology.hl7.org/CodeSystem/observation-category",
                                "code": "laboratory"}]}],
      "code": {"coding": [{"system": "http://loinc.org", "code": "1558-6",
                           "display": "Fasting glucose [Mass/volume] in Serum or Plasma"}]},
      "subject": {"reference": "Patient/p1"},
      "effectiveDateTime": "<conversion-run-date>T00:00:00Z",
      "valueQuantity": {"value": 95.0, "unit": "mg/dL",
                        "system": "http://unitsofmeasure.org", "code": "mg/dL"}
    },
    ...
  ],
  "rejects": [
    {
      "line": 5,
      "id": "p4",
      "reasons": ["invalid birthdate '1990-02-29': day is out of range for month (1990 is not a leap year)"]
    },
    ...
  ]
}
"""

from __future__ import annotations

import csv
import io
from datetime import date
from typing import Any

GENDER_CODES = {"male", "female", "other", "unknown"}

LOINC_GLUCOSE = {
    "system": "http://loinc.org",
    "code": "1558-6",
    "display": "Fasting glucose [Mass/volume] in Serum or Plasma",
}
OBS_CATEGORY = [
    {
        "coding": [
            {
                "system": "http://terminology.hl7.org/CodeSystem/observation-category",
                "code": "laboratory",
            }
        ]
    }
]
UCUM = "http://unitsofmeasure.org"


def _validate_row(row: dict[str, str], today: date, seen_ids: set[str]) -> list[str]:
    """Return a list of validation reasons; empty means the row is good."""
    reasons: list[str] = []

    rid = (row.get("id") or "").strip()
    if not rid:
        reasons.append("missing required field 'id'")
    elif rid in seen_ids:
        reasons.append(f"duplicate id '{rid}'")

    raw_birth = (row.get("birthdate") or "").strip()
    if not raw_birth:
        reasons.append("missing required field 'birthdate'")
    else:
        try:
            birth = date.fromisoformat(raw_birth)
        except ValueError as exc:
            reasons.append(f"invalid birthdate {raw_birth!r}: {exc}")
        else:
            if birth > today:
                reasons.append(
                    f"invalid birthdate {raw_birth!r}: date of birth is in the future"
                )

    gender = (row.get("gender") or "").strip().lower()
    if gender and gender not in GENDER_CODES:
        reasons.append(
            f"invalid gender {gender!r}: expected one of {sorted(GENDER_CODES)}"
        )

    glucose = (row.get("glucose_mg_dl") or "").strip()
    if glucose:
        try:
            if float(glucose) <= 0:
                raise ValueError("must be positive")
        except ValueError:
            reasons.append(f"invalid glucose_mg_dl {glucose!r}: not a positive number")

    return reasons


def _patient_from_row(row: dict[str, str]) -> dict[str, Any]:
    given = [g.strip() for g in (row.get("given") or "").split() if g.strip()]
    name: dict[str, Any] = {"family": row["family"].strip()}
    if given:  # empty given name is allowed -> omit the key entirely
        name["given"] = given

    patient: dict[str, Any] = {
        "resourceType": "Patient",
        "id": row["id"].strip(),
        "name": [name],
        "birthDate": row["birthdate"].strip(),
    }
    gender = (row.get("gender") or "").strip().lower()
    if gender:
        patient["gender"] = gender
    return patient


def _observation_from_row(row: dict[str, str], effective_date: str) -> dict[str, Any]:
    pid = row["id"].strip()
    return {
        "resourceType": "Observation",
        "id": f"obs-{pid}-glucose",
        "status": "final",
        "category": OBS_CATEGORY,
        "code": {"coding": [dict(LOINC_GLUCOSE)]},
        "subject": {"reference": f"Patient/{pid}"},
        "effectiveDateTime": f"{effective_date}T00:00:00Z",
        "valueQuantity": {
            "value": float(row["glucose_mg_dl"]),
            "unit": "mg/dL",
            "system": UCUM,
            "code": "mg/dL",
        },
    }


def convert(csv_text: str, *, today: date | None = None) -> dict[str, Any]:
    """Convert CSV text into patients/observations/rejects.

    Never raises on bad data: malformed rows land in ``rejects``.
    """
    today = today or date.today()
    seen_ids: set[str] = set()
    patients: list[dict[str, Any]] = []
    observations: list[dict[str, Any]] = []
    rejects: list[dict[str, Any]] = []

    reader = csv.DictReader(io.StringIO(csv_text))
    for line_no, row in enumerate(reader, start=2):  # line 1 is the header
        reasons = _validate_row(row, today, seen_ids)
        if reasons:
            rejects.append(
                {
                    "line": line_no,
                    "id": (row.get("id") or "").strip() or None,
                    "reasons": reasons,
                }
            )
            continue

        assert row["id"] is not None
        seen_ids.add(row["id"].strip())
        patients.append(_patient_from_row(row))
        if (row.get("glucose_mg_dl") or "").strip():
            observations.append(_observation_from_row(row, today.isoformat()))

    return {
        "patients": patients,
        "observations": observations,
        "rejects": rejects,
    }


def convert_fixture(fixture_text: str | None = None) -> dict[str, Any]:
    """Convert the bundled synthetic fixture (or provided CSV text)."""
    if fixture_text is None:
        import importlib.resources as res

        fixture_text = (
            res.files("csv_to_resource.fixtures").joinpath("patients.csv").read_text()
        )
    return convert(fixture_text)
